// Types for the wasm-bindgen glue module.
//
// `pkg/torille_wasm_bg.js` is generated by wasm-bindgen and ships
// without a `.d.ts` of its own (only the wrapper `torille_wasm.js`
// declares types, via its `@ts-self-types` comment). The demo's
// manual loader imports the glue directly -- it needs the module
// namespace to build the wasm's `./torille_wasm_bg.js` import
// object by hand -- so we declare it here.
//
// Every public name is aliased to the wrapper's declaration so the
// signatures have one source of truth; the only extra export is
// the internal hook the loader uses to attach the instance.
//
// The wildcard pattern matches the loader's relative specifier
// (`../../pkg/torille_wasm_bg.js`); wasm-pack regenerates pkg/
// on every rebuild, so a hand-written .d.ts next to the glue
// would not survive.
declare module '*/torille_wasm_bg.js' {
  import type * as Api from '../../pkg/torille_wasm.js';

  export const analyze_misspells: typeof Api.analyze_misspells;
  export const analyze_text: typeof Api.analyze_text;
  export const check: typeof Api.check;
  export const check_report: typeof Api.check_report;
  export const check_grammar_style_with_state: typeof Api.check_grammar_style_with_state;
  export const check_syntax_with_state: typeof Api.check_syntax_with_state;
  export const check_style: typeof Api.check_style;
  export const clear_state: typeof Api.clear_state;
  export const create_text_area_state: typeof Api.create_text_area_state;
  export const destroy_text_area_state: typeof Api.destroy_text_area_state;
  export const suggest_for_misspell: typeof Api.suggest_for_misspell;
  export const suggest_words: typeof Api.suggest_words;
  export const suggest_words_with_state: typeof Api.suggest_words_with_state;
  export const update_state_from_text: typeof Api.update_state_from_text;
  export const warm_caches: typeof Api.warm_caches;
  export const warm_form_set: typeof Api.warm_form_set;

  /** Attach a manually instantiated instance to the glue. */
  export function __wbg_set_wasm(exports: WebAssembly.Exports): void;
}
